# accept.ps1 -- scripted acceptance scenarios for the built game exe. Each scenario starts the game with the
# harness variables (KH2_KEYS, KH2_SCREENSHOT, ...), waits for it to save one screenshot and quit, then checks
# the log for required lines. Nobody watches video: the log lines are the evidence, the PNGs are for the
# orchestrator to LOOK at (Read tool) for things a log cannot show (no stray reticle, HUD present, no glitch).
#
#   powershell -NoProfile -ExecutionPolicy Bypass -File tools\accept.ps1              # all -> local\accept\<timestamp>\
#   powershell -NoProfile -ExecutionPolicy Bypass -File tools\accept.ps1 -Out local\accept\pre-shift5
#   powershell -NoProfile -ExecutionPolicy Bypass -File tools\accept.ps1 -Only combat-ground,look-around
#   powershell -NoProfile -ExecutionPolicy Bypass -File tools\accept.ps1 -SkipAudio   # skip the scenario that plays sound ~14 s
#
# It tests the checkout this script lives in (run that checkout's own copy). KH2_ISO comes from local\machine.ps1; the
# KH2_STATE files of the scenarios are untracked local\ files (this checkout's copy, else the main checkout's).
# The game runs without the memory cap (memory rule of 2026-10-22: normal game runs are uncapped).
# -Turbo -Jobs 8: the games run with KH2_TURBO=1 (fixed tick per frame, as fast as the CPU allows, silent), up to -Jobs at once,
# each with its own log and PNG; KH2_KEYS and KH2_SHOT_AT seconds become exact tick counts. Scenarios with Audio run afterwards,
# alone and in real time. Use 6 jobs while a build runs beside it. The summary lines are in finish order.
# Build first (cargo build -p kh2-app --bin kh2-game, or verify.ps1) -- the exe must be the code you want to test,
# and no other kh2-game window may be open. Game windows open and close during the run; do not touch the keyboard
# (the harness injects keys, but your own input would be mixed in).
# Expected-line patterns come from the worker reports of shift 4; if a pattern stops matching after a legitimate
# log-format change, fix the pattern here, do not delete the scenario.
param(
    [string]$Out = '',
    [string]$Exe = 'target\debug\kh2-game.exe',
    [string[]]$Only = @(),
    [switch]$SkipAudio,
    [switch]$Turbo,
    [int]$Jobs = 8
)
$Only = @($Only | ForEach-Object { $_ -split ',' } | Where-Object { $_ })   # -File passes "a,b" as one string
. (Join-Path $PSScriptRoot 'env.ps1')
Assert-KhHere 'accept.ps1'
Use-Machine @('KH2_ISO')
$root = $KhRoot
Set-Location $root
if (-not $Out) { $Out = 'local\accept\' + (Get-Date -Format 'yyyyMMdd-HHmm') }
New-Item -ItemType Directory -Force $Out | Out-Null
$Out = (Resolve-Path $Out).Path
$exeFull = (Resolve-Path $Exe).Path
$iso = $env:KH2_ISO

# local\ state files are git-ignored: in a worktree they do not exist, so fall back to the main checkout's copy.
function LocalFile([string]$rel) {
    $f = Get-KhLocal $rel
    if (-not $f) { throw "accept: local file not found: $rel (looked in $KhRoot and $KhMain)" }
    return $f
}

# Fight keys: F3 spawns a wave, Q locks on, W walks toward it, J attacks.
$fight = '2:F3,4:Q,5:W:1.5,7:J,7.4:J,7.8:J,8.4:J'
$airfight = '2:F3,4:Q,5:W:1.2,6.5:Space:0.6,7.0:J,7.4:J,7.8:J'
$long = '2:F3,3:Q,' + ((4..80 | ForEach-Object { '{0}:J' -f ($_ * 0.45 + 2.5) }) -join ',')
$press = ((200..800 | ForEach-Object { $_ / 20 }) -join ',')
$dusk = '6:Q,' + ((14..44 | ForEach-Object { '{0}:J' -f ($_ * 0.45) }) -join ',')
$seifer = '22:Q,' + ((50..64 | ForEach-Object { '{0}:J' -f ($_ * 0.45) }) -join ',')

$struggleWin = '6:Q,' + ((14..210 | ForEach-Object { '{0}:J' -f ($_ * 0.45) }) -join ',')

# Shift 17 enemy kinds (WP-ACC1): the recipes of docs\enemies.md. J every 0.45 s from $a to $b seconds.
function Jrun([double]$a, [double]$b) { ((0..[int](($b - $a) / 0.45)) | ForEach-Object { '{0}:J' -f [math]::Round($a + $_ * 0.45, 2) }) -join ',' }
